using Astrea.BattleActions;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

public class PurifyMinimunWaveCustomDescription : CustomBattleActionDescription
{
	private const string waveRequirementID = "WaveRequirement";

	private const string waveRequirementNoCostID = "WaveRequirementNoCost";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		PurifyMinimunWaveBaseAction purifyMinimunWaveBaseAction = battleAction as PurifyMinimunWaveBaseAction;
		string actionDescription = purifyMinimunWaveBaseAction.PurifyAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified));
		if (purifyMinimunWaveBaseAction.WaveCost > 0)
		{
			string localizedString = base.localizationManager.GetLocalizedString("WaveRequirement");
			return actionDescription + "\n" + Smart.Format(localizedString, purifyMinimunWaveBaseAction.MinimunWaveAmount, GetExtraActionDescription(battleAction, amountModified), base.localizationManager.GetLocalizedThenDecreaseEffect(purifyMinimunWaveBaseAction.WaveEffect, purifyMinimunWaveBaseAction.WaveCost), Smart.Format(base.localizationManager.GetLocalizedString("ThatEnemyEffect"), purifyMinimunWaveBaseAction.WaveAmountToApply, purifyMinimunWaveBaseAction.WaveEffectAction.Effect.GetEffectName()));
		}
		string localizedString2 = base.localizationManager.GetLocalizedString("WaveRequirementNoCost");
		return actionDescription + "\n" + Smart.Format(localizedString2, purifyMinimunWaveBaseAction.MinimunWaveAmount, GetExtraActionDescription(battleAction, amountModified));
	}

	protected virtual string GetExtraActionDescription(BattleAction battleAction, string amountModified)
	{
		return "";
	}
}
